{"path":"about.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8' />
  <meta name='viewport' content='width=device-width,initial-scale=1' />
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#0f1720;--card:rgba(255,255,255,0.06);--glass:rgba(255,255,255,0.08);--accent:#7dd3fc;--muted:#cbd5e1;--radius:14px}
    html,body{height:100%;margin:0;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;color:var(--muted);background:linear-gradient(180deg,#071026 0%, #0f1720 60%);-webkit-font-smoothing:antialiased}
    /* subtle patterned panel using inline SVG */
    body::before{content:'';position:fixed;inset:0;z-index:0;opacity:0.08;background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='200' height='200' viewBox='0 0 200 200'><defs><linearGradient id='g' x1='0' x2='1'><stop stop-color='%237dd3fc' stop-opacity='0.12'/><stop offset='1' stop-color='%2363b3ff' stop-opacity='0.04'/></linearGradient></defs><rect width='100%' height='100%' fill='url(%23g)'/></svg>");background-repeat:repeat;mix-blend-mode:screen}
    .wrapper{position:relative;z-index:1;max-width:980px;margin:48px auto;padding:36px}
    header{display:flex;align-items:center;justify-content:space-between;margin-bottom:20px}
    .brand{display:flex;align-items:center;gap:14px}
    .logo{width:56px;height:56px;border-radius:12px;background:linear-gradient(135deg,var(--glass),transparent);box-shadow:0 6px 20px rgba(2,6,23,0.6);display:flex;align-items:center;justify-content:center}
    .logo svg{width:34px;height:34px;opacity:0.95}
    nav a{color:var(--muted);text-decoration:none;margin-left:16px;font-size:14px}
    .hero{background:linear-gradient(180deg,rgba(255,255,255,0.03),transparent);backdrop-filter:blur(6px);border-radius:var(--radius);padding:26px;display:grid;grid-template-columns:1fr 320px;gap:22px;box-shadow:inset 0 1px 0 rgba(255,255,255,0.02)}
    h1{color:#e6f7ff;margin:0 0 8px 0;font-weight:600}
    p.lead{margin:0;color:var(--muted);line-height:1.45}
    .side{display:flex;flex-direction:column;gap:12px}
    .card{background:var(--card);padding:14px;border-radius:12px}
    .muted{color:#9fb0bf;font-size:13px}
    .cta{display:inline-block;padding:10px 14px;border-radius:10px;background:linear-gradient(90deg,var(--accent),#60a5fa);color:#022;font-weight:600;text-decoration:none}
    .small{font-size:13px}
    .accordion{margin-top:18px}
    .acc-item{border-radius:10px;overflow:hidden;margin-bottom:10px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent)}
    .acc-trigger{display:flex;justify-content:space-between;padding:12px 14px;cursor:pointer;align-items:center}
    .acc-content{max-height:0;overflow:hidden;padding:0 14px;transition:max-height 260ms ease}
    .acc-content p{margin:12px 0;color:var(--muted);font-size:14px}
    footer.crisis{margin-top:14px;padding:12px 14px;border-radius:10px;background:rgba(255,250,250,0.02);font-size:13px;color:#ffdcdc}
    .meta{font-size:13px;color:var(--muted);margin-top:10px}
    @media(max-width:820px){.hero{grid-template-columns:1fr;padding:18px}.side{order:2}}
  </style>
</head>
<body>
  <div class='wrapper'>
    <header>
      <div class='brand'>
        <div class='logo' aria-hidden='true'>
          <svg viewBox='0 0 24 24' fill='none' xmlns='http://www.w3.org/2000/svg'><circle cx='12' cy='12' r='10' stroke='rgba(255,255,255,0.12)' stroke-width='1.5'/><path d='M7 13c1.5-2 3-4 5-4s3.5 2 5 4' stroke='white' stroke-opacity='0.9' stroke-width='1.4' stroke-linecap='round' stroke-linejoin='round'/></svg>
        </div>
        <div>
          <div style='color:#e6f7ff;font-weight:600'>{{BUSINESS_NAME}}</div>
          <div class='muted small'>Warm, steady clinical care — ongoing membership or focused engagements</div>
        </div>
      </div>
      <nav>
        <a href='index.html'>Home</a>
        <a href='specialties.html'>Services</a>
        <a href='approach.html'>How I Work</a>
        <a href='book.html'>Book</a>
        <a href='contact.html'>Connect</a>
      </nav>
    </header>

    <section class='hero' aria-labelledby='about-hero'>
      <div>
        <h1 id='about-hero'>About my practice</h1>
        <p class='lead'>I work with adults navigating life shifts, persistent patterns that feel stuck, and moments when values and choices don't line up with living as you intend. My approach is rooted in evidence-informed methods blended with practical, present-focused work.
        </p>

        <div class='card' style='margin-top:18px'>
          <strong style='color:#e6f7ff'>Membership model</strong>
          <p class='small muted' style='margin-top:8px'>Members receive regular sessions, a care plan we shape together, and flexible short blocks when life spikes. Membership is intended for ongoing therapeutic partnership rather than quick fixes.</p>
          <div style='margin-top:10px'><a class='cta' href='{{PRIMARY_CTA_URL}}'>{{PRIMARY_CTA_LABEL}}</a></div>
        </div>

        <div class='meta'>Sessions offered via secure telehealth. Sliding-scale availability may be discussed in a brief intake.</div>
      </div>

      <aside class='side'>
        <div class='card'>
          <div style='font-weight:600;color:#e6f7ff'>Quick practicals</div>
          <div class='small muted' style='margin-top:8px'>Phone: {{PHONE}}<br/>Email: <a href='mailto:{{EMAIL}}' style='color:var(--accent)'>{{EMAIL}}</a></div>
        </div>

        <div class='card accordion' aria-hidden='false'>
          <div class='acc-item'>
            <button class='acc-trigger' aria-expanded='false'>Session boundaries & confidentiality <span class='muted'>▾</span></button>
            <div class='acc-content'>
              <p>I keep clinical notes and store them securely. Notes are used to support continuity of care; they are not shared without your written permission except where legally required (e.g. imminent harm, court-ordered requests, or mandated reporting). We can discuss what I document if that feels helpful.</p>
            </div>
          </div>

          <div class='acc-item'>
            <button class='acc-trigger' aria-expanded='false'>Scope & limits of practice <span class='muted'>▾</span></button>
            <div class='acc-content'>
              <p>Therapy focuses on emotional, behavioral, and relational concerns. I do not provide legal, financial, or medical diagnoses. When needs exceed my scope, I will discuss referrals or collaborative care options.</p>
            </div>
          </div>
        </div>

        <div class='card' style='font-size:13px'>
          <strong style='color:#e6f7ff'>Accessibility</strong>
          <div class='muted small' style='margin-top:8px'>I aim to make work accessible. If cost, scheduling, or platform access is a barrier, mention it during the intake so we can explore options.</div>
        </div>
      </aside>

    </section>

    <div class='card' style='margin-top:18px'>
      <strong style='color:#e6f7ff'>Professional note</strong>
      <p class='small muted' style='margin-top:8px'>I hold a clinical license and maintain required continuing education and insurance. This space is intended for therapeutic work; if you are in immediate danger or experiencing a medical emergency, please call local emergency services or a crisis hotline.</p>
    </div>

    <div class='card' style='margin-top:12px'>
      <div style='font-weight:600;color:#ffdede'>Respectful crisis information</div>
      <div style='margin-top:8px;font-size:13px;color:#ffdede'>If you are in crisis and at risk of harming yourself or others, call your local emergency number or a crisis line immediately. If you are in the United States, you can call or text 988 for the Suicide & Crisis Lifeline. For other locations, please use local emergency resources.</div>
    </div>

  </div>

  <script>
    // accordion behavior
    document.querySelectorAll('.acc-trigger').forEach(btn => {
      btn.addEventListener('click', () => {
        const expanded = btn.getAttribute('aria-expanded') === 'true';
        btn.setAttribute('aria-expanded', !expanded);
        const content = btn.nextElementSibling;
        if(!expanded){
          content.style.maxHeight = content.scrollHeight + 'px';
        } else {
          content.style.maxHeight = '0';
        }
      });
    });
  </script>
</body>
</html>"} 
{"path":"specialties.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8' />
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>Services — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#081223;--panel:rgba(255,255,255,0.03);--glass:rgba(255,255,255,0.06);--accent:#8bd5ff;--muted:#c6d5df}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Arial;background:linear-gradient(180deg,#04101a,#081223);color:var(--muted);-webkit-font-smoothing:antialiased}
    .wrap{max-width:1000px;margin:36px auto;padding:28px}
    header{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}
    nav a{color:var(--muted);text-decoration:none;margin-left:14px}
    h1{color:#effbff;margin:0 0 8px 0}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:18px}
    .panel{background:var(--panel);padding:18px;border-radius:12px;backdrop-filter:blur(6px)}
    .pill{display:inline-block;background:rgba(255,255,255,0.02);padding:6px 10px;border-radius:999px;font-size:13px;color:var(--muted)}
    ul.specialties{list-style:none;padding:0;margin:8px 0 0 0}
    ul.specialties li{padding:10px 8px;border-radius:8px;margin-bottom:8px;background:linear-gradient(180deg,rgba(255,255,255,0.01),transparent)}
    .method{font-weight:600;color:#e8fbff}
    .muted{color:var(--muted);font-size:14px}
    .mood-box{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}
    .mood{padding:8px 10px;background:rgba(255,255,255,0.02);border-radius:10px;cursor:pointer}
    .mood.active{outline:2px solid rgba(139,213,255,0.12);background:linear-gradient(90deg,var(--accent),#61aefc);color:#022}
    .cta{display:inline-block;padding:10px 12px;border-radius:10px;background:linear-gradient(90deg,var(--accent),#60a5fa);color:#022;text-decoration:none;font-weight:600;margin-top:12px}
    .notes{font-size:13px;color:#9fb0bf;margin-top:10px}
    @media(max-width:860px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <div class='wrap'>
    <header>
      <div>
        <div style='color:#e6f7ff;font-weight:600'>{{BUSINESS_NAME}}</div>
        <div class='muted small'>Practical therapy offerings and membership options</div>
      </div>
      <nav>
        <a href='index.html'>Welcome</a>
        <a href='about.html'>Meet</a>
        <a href='approach.html'>Process</a>
        <a href='book.html'>Schedule</a>
      </nav>
    </header>

    <main class='grid'>
      <section class='panel'>
        <h1>Services & specialties</h1>
        <p class='muted'>I work primarily with adults on relationship shifts, anxiety that affects daily functioning, career transitions, and patterns that repeat from old wounds. Below are common areas people bring to therapy.</p>

        <ul class='specialties' aria-label='specialties list'>
          <li><div class='method'>Relationship patterns</div><div class='muted' style='margin-top:6px'>Working with recurring relational dynamics — communication, boundaries, and repair.</div></li>
          <li><div class='method'>Anxiety & performance pressure</div><div class='muted' style='margin-top:6px'>Practical strategies to reduce interference with daily tasks and values-driven action.</div></li>
          <li><div class='method'>Life transitions</div><div class='muted' style='margin-top:6px'>Decision points such as career change, parenting shifts, or ending relationships.</div></li>
          <li><div class='method'>Patterns from earlier experience</div><div class='muted' style='margin-top:6px'>Exploring how earlier attachments and habits show up now and influence choices.</div></li>
        </ul>

        <div class='notes'>If you are unsure what to expect, we can begin with a brief consultation to see fit and talk about pacing.</div>
      </section>

      <aside class='panel'>
        <div style='display:flex;justify-content:space-between;align-items:center'>
          <div style='font-weight:600;color:#e6f7ff'>Mood-to-Method selector</div>
        </div>
        <p class='muted' style='margin-top:8px'>Choose a current state and see a recommended therapeutic focus and a tailored invitation to begin.</p>

        <div class='mood-box' id='moodBox' role='tablist' aria-label='Mood selector'>
          <button class='mood' data-key='overwhelmed'>Overwhelmed</button>
          <button class='mood' data-key='stuck'>Stuck</button>
          <button class='mood' data-key='shaky'>Shaky after change</button>
          <button class='mood' data-key='planning'>Planning next steps</button>
        </div>

        <div id='recommend' style='margin-top:12px'>
          <div style='font-weight:600;color:#e6f7ff' id='recTitle'>Choose a state</div>
          <div class='muted' id='recBody' style='margin-top:8px'>Selecting a state will show a suggested focus and a phrase to start.</div>
          <a id='recCTA' class='cta' href='{{PRIMARY_CTA_URL}}' style='display:inline-block;margin-top:10px'>{{PRIMARY_CTA_LABEL}}</a>
        </div>

        <div class='muted' style='margin-top:10px;font-size:13px'>Sessions available as single-session blocks or ongoing membership engagements.</div>
      </aside>
    </main>
  </div>

  <script>
    const map = {
      overwhelmed: {
        title: 'Short-term stabilization',
        body: 'Practical safety planning, slowing reactivity, and immediate coping strategies. Often one to four focused sessions to regain steadiness.',
        cta: 'Request a stabilization visit'
      },
      stuck: {
        title: 'Pattern work',
        body: 'We map recurring behaviors, try small experiments, and trace ways to test new choices. Good for sustained membership work.',
        cta: 'Explore the membership'
      },
      shaky: {
        title: 'Transition support',
        body: 'Normalize the aftereffects of change, clarify values, and plan manageable steps. Typically short blocks with defined aims.',
        cta: 'Book a transition session'
      },
      planning: {
        title: 'Strategic planning',
        body: 'Concrete planning sessions focusing on decision-making frameworks and preparing for conversations or changes ahead.',
        cta: 'Schedule a planning consult'
      }
    };

    const moodBox = document.getElementById('moodBox');
    const recTitle = document.getElementById('recTitle');
    const recBody = document.getElementById('recBody');
    const recCTA = document.getElementById('recCTA');

    moodBox.addEventListener('click', e => {
      const btn = e.target.closest('button[data-key]');
      if(!btn) return;
      document.querySelectorAll('.mood').forEach(m => m.classList.remove('active'));
      btn.classList.add('active');
      const key = btn.getAttribute('data-key');
      const item = map[key];
      recTitle.textContent = item.title;
      recBody.textContent = item.body;
      recCTA.textContent = item.cta;
      // update CTA URL to include mood as query
      const base = '{{PRIMARY_CTA_URL}}';
      recCTA.href = base + (base.includes('?') ? '&' : '?') + 'mood=' + encodeURIComponent(key);
    });
  </script>
</body>
</html>"} 
{"path":"approach.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8' />
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>How I Work — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#071022;--glass:rgba(255,255,255,0.05);--card:rgba(255,255,255,0.03);--accent:#76d0ff;--muted:#c7d7e2}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;background:radial-gradient(1200px 600px at 10% 10%, rgba(118,208,255,0.06), transparent),linear-gradient(180deg,#021018,#071022);color:var(--muted);-webkit-font-smoothing:antialiased}
    .wrap{max-width:950px;margin:36px auto;padding:26px}
    header{display:flex;justify-content:space-between;align-items:center}
    nav a{color:var(--muted);text-decoration:none;margin-left:14px}
    h1{color:#e8fbff;margin-bottom:6px}
    .lead{color:var(--muted);margin-bottom:14px}
    .flow{display:flex;gap:14px;flex-wrap:wrap}
    .step{flex:1 1 220px;background:var(--card);padding:14px;border-radius:12px;backdrop-filter:blur(6px)}
    .step h3{margin:0 0 6px 0;color:#e9fbff}
    .step p{margin:0;color:var(--muted);font-size:14px}
    .panel{margin-top:18px;padding:14px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);border-radius:12px}
    .mood{display:flex;gap:8px;margin-top:10px}
    .mood button{padding:8px 10px;border-radius:10px;background:rgba(255,255,255,0.02);color:var(--muted);border:none;cursor:pointer}
    .mood button.active{background:linear-gradient(90deg,var(--accent),#58aef7);color:#022;font-weight:600}
    .cta{display:inline-block;padding:10px 12px;border-radius:10px;background:linear-gradient(90deg,var(--accent),#60a5fa);color:#022;text-decoration:none;font-weight:600;margin-top:12px}
    .accordion{margin-top:14px}
    .acc-item{background:rgba(255,255,255,0.02);border-radius:10px;margin-bottom:10px}
    .acc-trigger{display:flex;justify-content:space-between;padding:12px;border-radius:10px;width:100%;background:transparent;border:0;color:var(--muted);cursor:pointer}
    .acc-content{max-height:0;overflow:hidden;padding:0 12px;transition:max-height 250ms ease}
    .acc-content p{margin:12px 0;color:var(--muted)}
    .crisis{margin-top:12px;padding:12px;border-radius:10px;background:rgba(255,205,205,0.03);color:#ffdede}
    @media(max-width:760px){.flow{flex-direction:column}}
  </style>
</head>
<body>
  <div class='wrap'>
    <header>
      <div>
        <div style='font-weight:600;color:#e6fbff'>How I work</div>
        <div class='lead'>A collaborative, pragmatic rhythm — we name what's important, try small changes, and adjust based on what helps.</div>
      </div>
      <nav>
        <a href='index.html'>Start</a>
        <a href='about.html'>About</a>
        <a href='specialties.html'>Services</a>
        <a href='book.html'>Schedule</a>
      </nav>
    </header>

    <section class='flow' aria-labelledby='process'>
      <div class='step'>
        <h3>1. Brief intake</h3>
        <p>We clarify immediate concerns, practical constraints, and what a helpful next step might look like.</p>
      </div>
      <div class='step'>
        <h3>2. Collaborative plan</h3>
        <p>Together we set clear goals and decide whether a short block or ongoing membership feels right.</p>
      </div>
      <div class='step'>
        <h3>3. Active, practical work</h3>
        <p>Sessions focus on small experiments, skills practice, and making decisions that align with your values.</p>
      </div>
    </section>

    <div class='panel'>
      <strong style='color:#e6fbff'>Mood-to-Method: pick how you feel now</strong>
      <div class='mood' role='tablist' aria-label='Mood to method'>
        <button data-key='tense'>Tense or reactive</button>
        <button data-key='numb'>Numb or detached</button>
        <button data-key='confused'>Confused about next steps</button>
        <button data-key='ready'>Ready to try new behaviors</button>
      </div>

      <div id='methodRec' style='margin-top:12px'>
        <div id='methodTitle' style='font-weight:600;color:#e6fbff'>Select a mood</div>
        <div id='methodBody' class='muted' style='margin-top:8px'>The recommendation will appear here; the CTA updates to a relevant invitation.</div>
        <a id='methodCTA' class='cta' href='{{PRIMARY_CTA_URL}}'>{{PRIMARY_CTA_LABEL}}</a>
      </div>
    </div>

    <div class='panel accordion'>
      <div class='acc-item'>
        <button class='acc-trigger' aria-expanded='false'>Boundaries & confidentiality <span class='muted'>▾</span></button>
        <div class='acc-content'>
          <p>Clinical records are held securely. I will not share your information without your consent except in limited situations required by law (e.g., imminent danger, mandated reporting). We can talk about privacy preferences during intake.</p>
        </div>
      </div>
      <div class='acc-item'>
        <button class='acc-trigger' aria-expanded='false'>Limits of remote care <span class='muted'>▾</span></button>
        <div class='acc-content'>
          <p>Telehealth is a main option. If circumstances suggest in-person or more intensive support is needed, I will discuss referral or collaboration with other providers.</p>
        </div>
      </div>
    </div>

    <div class='crisis' role='note'>
      If you are at immediate risk of harming yourself or someone else, call local emergency services right away. In the U.S., dialing or texting 988 connects you to the Suicide & Crisis Lifeline. If you are elsewhere, please use your local emergency resources.
    </div>

  </div>

  <script>
    // Mood-to-method implementation that morphs recommendation and CTA
    const map = {
      tense: {
        title: 'Grounding & regulation',
        body: 'Short, practical sessions focused on reducing intensity, improving safety, and stabilizing day-to-day functioning.',
        cta: 'Book a regulation visit'
      },
      numb: {
        title: 'Reconnect & notice',
        body: 'Gentle, exploratory work to increase contact with feelings, values, and small moments of choice.',
        cta: 'Begin with a reconnect session'
      },
      confused: {
        title: 'Clarify & plan',
        body: 'Decision-focused sessions to weigh options, set criteria, and map actionable next steps.',
        cta: 'Schedule a planning consult'
      },
      ready: {
        title: 'Experiment & practice',
        body: 'Hands-on sessions to try new behaviors, review results, and iterate what helps in daily life.',
        cta: 'Start a short practice block'
      }
    };

    document.querySelectorAll('[data-key]').forEach(btn => {
      btn.addEventListener('click', () => {
        document.querySelectorAll('[data-key]').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        const key = btn.getAttribute('data-key');
        const item = map[key];
        document.getElementById('methodTitle').textContent = item.title;
        document.getElementById('methodBody').textContent = item.body;
        const methodCTA = document.getElementById('methodCTA');
        methodCTA.textContent = item.cta;
        const base = '{{PRIMARY_CTA_URL}}';
        methodCTA.href = base + (base.includes('?') ? '&' : '?') + 'mode=' + encodeURIComponent(key);
      });
    });

    // accessible accordion
    document.querySelectorAll('.acc-trigger').forEach(btn => {
      btn.addEventListener('click', () => {
        const content = btn.nextElementSibling;
        const expanded = btn.getAttribute('aria-expanded') === 'true';
        btn.setAttribute('aria-expanded', String(!expanded));
        if(!expanded){
          content.style.maxHeight = content.scrollHeight + 'px';
        } else {
          content.style.maxHeight = '0';
        }
      });
    });
  </script>
</body>
</html>"} 
